package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"syscall"
)

// Manual review and false-positive analysis work strictly on top of
// archived evidence: submitting a review, querying revision history and
// re-evaluating a height range never need the original input files, never
// contact any network, never re-write a report, the enabled version or an
// alert record, and never trigger or revoke alerts.

// Review statuses. A human marks an archived conclusion either as a real
// risk or as a false positive; submitting "unreviewed" withdraws earlier
// judgments of the same object without deleting the history.
const (
	ReviewStatusReal          = "real"
	ReviewStatusFalsePositive = "false_positive"
	ReviewStatusUnreviewed    = "unreviewed"
)

// Evaluation buckets for original conclusions carrying a valid review:
// real risks split into retained vs missed, false positives into still hit
// vs eliminated. Candidate hits without a valid review are pending.
const (
	BucketRetained   = "retained"
	BucketMissed     = "missed"
	BucketStillHit   = "stillHit"
	BucketEliminated = "eliminated"
	BucketPending    = "pending"
)

// ErrUnknownConclusion reports a review action targeting a conclusion that
// no archived report carries.
var ErrUnknownConclusion = errors.New("unknown conclusion")

// ErrReviewConflict reports a submission whose expectedVersion is behind the
// object's current version.
var ErrReviewConflict = errors.New("review version conflict")

// ErrSubmissionConflict reports a submission ID already stored with
// different field values. Submission IDs are unique archive-wide.
var ErrSubmissionConflict = errors.New("submission id already used with different content")

// conclusionKey is the reviewed object's identity: chain, block hash,
// victim tx hash and conclusion kind. It deliberately excludes the alert
// channel, and blocks at the same height with different hashes are
// different objects.
type conclusionKey struct {
	chainID   string
	blockHash string
	txHash    string
	kind      string
}

// ReviewRevision is one immutable submission. Revisions are append-only:
// rejudgments and withdrawals add a new revision while every earlier one is
// retained. ExpectedVersion records the optimistic-concurrency base the
// submitter believed in (0 for the first submission), keeping each
// revision's full submission content auditable.
type ReviewRevision struct {
	Version         int    `json:"version"`
	SubmissionID    string `json:"submissionId"`
	Operator        string `json:"operator"`
	Reason          string `json:"reason"`
	Status          string `json:"status"`
	ExpectedVersion int    `json:"expectedVersion"`
}

// ReviewObject is the append-only revision stream for one conclusion
// identity. The current version is len(Revisions); the current status is
// the last revision's status (an "unreviewed" tail means withdrawn).
type ReviewObject struct {
	ChainID   string           `json:"chainId"`
	BlockHash string           `json:"blockHash"`
	TxHash    string           `json:"txHash"`
	Kind      string           `json:"kind"`
	Revisions []ReviewRevision `json:"revisions"`
}

func (o ReviewObject) key() conclusionKey {
	return conclusionKey{o.ChainID, o.BlockHash, o.TxHash, o.Kind}
}

// ReviewSubmission is one submitted review.
type ReviewSubmission struct {
	ChainID         string
	BlockHash       string
	TxHash          string
	Kind            string
	SubmissionID    string
	Operator        string
	Reason          string
	Status          string
	ExpectedVersion int
}

func (s ReviewSubmission) key() conclusionKey {
	return conclusionKey{s.ChainID, s.BlockHash, s.TxHash, s.Kind}
}

// contentEqual reports whether two submissions carry identical field
// values, including the target identity and the expected version.
func (s ReviewSubmission) contentEqual(o ReviewSubmission) bool {
	return s == o
}

func (s ReviewSubmission) revision(version int) ReviewRevision {
	return ReviewRevision{
		Version:         version,
		SubmissionID:    s.SubmissionID,
		Operator:        s.Operator,
		Reason:          s.Reason,
		Status:          s.Status,
		ExpectedVersion: s.ExpectedVersion,
	}
}

// reviewSpec mirrors one submission document. Pointers distinguish missing
// fields from explicit zero values; the decoder rejects unknown fields.
type reviewSpec struct {
	ChainID         *string `json:"chainId"`
	BlockHash       *string `json:"blockHash"`
	TxHash          *string `json:"txHash"`
	Kind            *string `json:"kind"`
	SubmissionID    *string `json:"submissionId"`
	Operator        *string `json:"operator"`
	Reason          *string `json:"reason"`
	Status          *string `json:"status"`
	ExpectedVersion *int    `json:"expectedVersion"`
}

// reviewRule identifies one business limit every review submission must
// satisfy, however it was supplied (JSON spec or direct call).
type reviewRule int

const (
	ruleBlankString        reviewRule = iota // a text field is empty or all whitespace
	ruleKnownKind                            // the conclusion kind is not sandwich/displacement
	ruleKnownStatus                          // the status is not real/false_positive/unreviewed
	ruleNonNegativeVersion                   // the expected version is negative
)

// reviewViolation is the first business limit a submission breaks. Both
// submission entries render it with their own longstanding wording.
type reviewViolation struct {
	rule    reviewRule
	field   string // the submission field the rule rejected, in JSON spelling
	value   string // the offending kind, status or text value
	version int    // the offending expected version
}

// validateReviewSubmission applies the business limits every review
// submission must satisfy, in the order both entries have always reported
// them: chain, block hash, victim tx hash, kind, submission id, operator,
// reason, status, then the expected version. It only judges the values —
// nothing is trimmed, re-cased or replaced — and returns the first
// violation, or nil when the submission is valid.
func validateReviewSubmission(sub ReviewSubmission) *reviewViolation {
	for _, f := range []struct{ field, value string }{
		{"chainId", sub.ChainID},
		{"blockHash", sub.BlockHash},
		{"txHash", sub.TxHash},
		{"kind", sub.Kind},
	} {
		if strings.TrimSpace(f.value) == "" {
			return &reviewViolation{rule: ruleBlankString, field: f.field, value: f.value}
		}
	}
	if sub.Kind != SuppressSandwich && sub.Kind != SuppressDisplacement {
		return &reviewViolation{rule: ruleKnownKind, field: "kind", value: sub.Kind}
	}
	for _, f := range []struct{ field, value string }{
		{"submissionId", sub.SubmissionID},
		{"operator", sub.Operator},
		{"reason", sub.Reason},
		{"status", sub.Status},
	} {
		if strings.TrimSpace(f.value) == "" {
			return &reviewViolation{rule: ruleBlankString, field: f.field, value: f.value}
		}
	}
	switch sub.Status {
	case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
	default:
		return &reviewViolation{rule: ruleKnownStatus, field: "status", value: sub.Status}
	}
	if sub.ExpectedVersion < 0 {
		return &reviewViolation{rule: ruleNonNegativeVersion, field: "expectedVersion", version: sub.ExpectedVersion}
	}
	return nil
}

// specError renders the violation with the JSON spec entry's wording.
func (v *reviewViolation) specError() error {
	switch v.rule {
	case ruleBlankString:
		return fmt.Errorf("%s must be a non-empty string", v.field)
	case ruleKnownKind:
		return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, v.value)
	case ruleKnownStatus:
		return fmt.Errorf("invalid status %q (want %s, %s or %s)",
			v.value, ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed)
	case ruleNonNegativeVersion:
		return fmt.Errorf("expectedVersion must be non-negative, got %d", v.version)
	}
	return nil
}

// submitError renders the violation with the direct submission entry's
// wording. That entry never blank-checked kind and status separately: a
// blank kind reads as an unknown kind and a blank status as an invalid one,
// and its invalid-status message carries no candidate list.
func (v *reviewViolation) submitError() error {
	switch v.rule {
	case ruleBlankString:
		switch v.field {
		case "kind":
			return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, v.value)
		case "status":
			return fmt.Errorf("invalid status %q", v.value)
		default:
			return fmt.Errorf("%s must be a non-empty string", v.field)
		}
	case ruleKnownStatus:
		return fmt.Errorf("invalid status %q", v.value)
	default:
		return v.specError()
	}
}

// ErrReviewTrailingData reports non-whitespace content after the single JSON
// object that makes up a review submission: a second object, an unmatched
// } or ], another JSON value or any other character.
var ErrReviewTrailingData = errors.New("unexpected trailing data after review spec")

// reviewFields lists every field name a review submission document may
// declare, in the struct's JSON spelling. The scanner uses the table both
// to know which values are ordinary scalars and to catch a known field
// declared twice; a review document is flat, so no nested table exists.
var reviewFields = []string{
	"chainId", "blockHash", "txHash", "kind",
	"submissionId", "operator", "reason", "status", "expectedVersion",
}

// reviewScanPolicy validates the shape of a review document with the shared
// scanner, the same machine rule-version and suppression registrations use.
// A review document is flat, so no nested table exists, and only known
// fields take part in duplicate detection (an unknown key is left for the
// typed decoder to reject).
var reviewScanPolicy = specPolicy{
	topObject:          "review spec",
	known:              fieldTable(reviewFields...),
	rejectExactUnknown: false,
	firstTokenError: func(err error) error {
		if errors.Is(err, io.EOF) {
			return errors.New("review spec must be a JSON object, got empty input")
		}
		return fmt.Errorf("invalid review spec: %w", err)
	},
	nonObject: func(tok json.Token) error {
		if tok == nil {
			return errors.New("review spec must be a single JSON object, got null")
		}
		if d, ok := tok.(json.Delim); ok && d == '[' {
			return errors.New("review spec must be a single JSON object, got array")
		}
		return fmt.Errorf("review spec must be a single JSON object, got %s", jsonTokenName(tok))
	},
	wrap: func(err error) error {
		return fmt.Errorf("invalid review spec: %w", err)
	},
	duplicate: func(_ string, canonical, first, spelling string) error {
		return fmt.Errorf("invalid review spec: duplicate field %q (declared as %q and %q)", canonical, first, spelling)
	},
	trailing: reviewTrailingData,
}

// reviewTrailingData names the first non-whitespace byte after the closed
// object, so an unmatched '}' or ']' is reported as trailing content rather
// than as a syntax error; only whitespace may follow the object.
func reviewTrailingData(raw []byte, offset int) error {
	rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
	if len(rest) > 0 {
		return fmt.Errorf("%w: %s after closing object", ErrReviewTrailingData, trailingTokenName(rest[0]))
	}
	return nil
}

// validateReviewDocument proves raw holds exactly one complete JSON object
// — leading and trailing whitespace is fine, but empty input, whitespace
// only, arrays, null, scalars and unclosed objects are not — and that no
// byte other than whitespace follows the closing brace. Inside the object
// every known field may be declared at most once: field names are compared
// after JSON unescaping with the decoder's own field-name folding, so two
// spellings that resolve to the same field — differing only in case, like
// status and STATUS, or in a compatibility character, like U+017F for s —
// count as one duplicate declaration even when both carry the same value,
// and the whole document is rejected rather than one value silently
// winning. Brackets inside string values are field content, not structure:
// the tokenizer only treats delimiters outside strings as object
// boundaries.
func validateReviewDocument(raw []byte) error {
	return scanJSONObject(raw, reviewScanPolicy)
}

// ParseReviewSubmission validates one submission document. The document
// must contain exactly one complete JSON object (leading and trailing
// spaces, tabs and newlines allowed): empty input, whitespace only, an
// array, null, any other standalone value or an unclosed object fail, and
// a second object or value, an unmatched } or ] or any other non-whitespace
// byte after the closing brace fails as trailing data — the valid prefix is
// never accepted on its own. Every supported field may be declared at most
// once: two declarations of the same field — under any spellings the
// decoder folds together, and even when both carry the same value or one
// carries null — are a duplicate and reject the whole document rather than
// letting a later value override an earlier one. Identity fields and
// operator/reason/submissionId must be non-empty, the status must be one of
// real, false_positive or unreviewed, expectedVersion must be a
// non-negative integer, and the kind must be a known conclusion kind.
func ParseReviewSubmission(raw []byte) (ReviewSubmission, error) {
	if err := validateReviewDocument(raw); err != nil {
		return ReviewSubmission{}, err
	}
	var spec reviewSpec
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&spec); err != nil {
		return ReviewSubmission{}, fmt.Errorf("invalid review spec: %w", err)
	}
	// A field the document never declares decodes as a nil pointer and
	// reaches the shared business check as the empty value. The document's
	// own missing-field error for that field precedes its content check, so
	// a blank-value violation on an undeclared field is reported as the
	// missing field instead.
	missing := map[string]bool{}
	value := func(field string, p *string) string {
		if p == nil {
			missing[field] = true
			return ""
		}
		return *p
	}
	sub := ReviewSubmission{
		ChainID:      value("chainId", spec.ChainID),
		BlockHash:    value("blockHash", spec.BlockHash),
		TxHash:       value("txHash", spec.TxHash),
		Kind:         value("kind", spec.Kind),
		SubmissionID: value("submissionId", spec.SubmissionID),
		Operator:     value("operator", spec.Operator),
		Reason:       value("reason", spec.Reason),
		Status:       value("status", spec.Status),
	}
	if spec.ExpectedVersion != nil {
		sub.ExpectedVersion = *spec.ExpectedVersion
	}
	if v := validateReviewSubmission(sub); v != nil {
		if v.rule == ruleBlankString && missing[v.field] {
			return ReviewSubmission{}, fmt.Errorf("%s is required (non-empty string)", v.field)
		}
		return ReviewSubmission{}, v.specError()
	}
	if spec.ExpectedVersion == nil {
		return ReviewSubmission{}, errors.New("expectedVersion is required (non-negative integer)")
	}
	return sub, nil
}

// SubmitReviewResult is the outcome of one submission attempt. Created is
// false when an identical submission (same ID and same field values) was
// retried: in that case Revision is the original revision and no new one is
// appended, even when the object was rejudged or withdrawn later.
type SubmitReviewResult struct {
	Created   bool           `json:"created"`
	ChainID   string         `json:"chainId"`
	BlockHash string         `json:"blockHash"`
	TxHash    string         `json:"txHash"`
	Kind      string         `json:"kind"`
	Status    string         `json:"status"`
	Version   int            `json:"version"`
	Revision  ReviewRevision `json:"revision"`
}

// SubmitReview validates and stores one review revision. The target
// conclusion must exist in the archive, and the report that carries it must
// still carry an intact version declaration: once the conclusion is found,
// its report's saved declaration is re-validated from its raw bytes with
// the exact integrity proof a report query, a comparison, alert generation
// and the review history/evaluation paths enforce — a non-empty version
// identifier, both the sandwich and displacement rules each with a boolean
// enabled and an integer severity 1-5, and a displacement multiplier
// 2-100 — before the submission is accepted in any way. A missing or null
// field or rule object, a wrong type, an out-of-range number, an unknown
// field or rule, or a field declared twice in one object (an exact repeat,
// an escaped spelling or a case-only spelling naming the same field, even
// with identical values) makes the saved declaration corrupt; an explicit
// enabled:false is a legal off state but the disabled rule still has to
// carry complete, in-range parameters. Only an old-format record with no
// "version" key at all keeps the built-in interpretation: a written null,
// an empty object or a partial declaration is corruption, and an id of
// "builtin" is validated like every other id rather than bypassing the
// check. A legal declaration is used exactly as saved, never completed from
// defaults, the currently enabled or a same-id registered version, and the
// saved id need not still be registered.
//
// On corruption the whole submission fails with ErrCorruptVersion naming
// the target chain and block, the readable saved version id and the
// offending rule or field — whether the submission is a first one, a
// rejudgment, a withdrawal or an identical retry carrying a submissionId
// already stored: the proof precedes submission-id reuse, version-conflict
// and object-version handling, so no retry of the same submission id can
// mask the damage, no result JSON is produced, no submission id is
// consumed, no revision or object version changes, and the archive bytes —
// the damaged declaration included — are rewritten by nothing. A target no
// archived conclusion matches still fails as ErrUnknownConclusion, and an
// identity the corrupt report does not carry never opens that report's
// declaration.
//
// With the declaration proved, the first submission for an object must
// carry expectedVersion 0; every later one must carry the object's current
// version, otherwise the submission is rejected without touching stored
// data. Rejudgments and withdrawals append; older revisions stay.
// Identical retries (same archive-unique submission ID and identical
// fields) return the original revision. The whole update is one atomic
// commit under the archive lock, so concurrent submissions serialize and a
// stale concurrent submission can never overwrite another operator's
// revision.
func SubmitReview(dir string, sub ReviewSubmission) (SubmitReviewResult, error) {
	if v := validateReviewSubmission(sub); v != nil {
		return SubmitReviewResult{}, v.submitError()
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return SubmitReviewResult{}, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return SubmitReviewResult{}, err
	}
	defer lock.Close()

	// Decode with every stored record and registered version kept as its
	// raw stored document, the same shape a replay, a report query and a
	// comparison read, so the target report's declaration is re-validated
	// from those bytes rather than decoded into silently zeroed parameters
	// or explained as the built-in rules from a written null, and so a
	// successful commit writes every stored record and version back
	// byte-for-byte in content instead of re-encoding the declaration this
	// judgment must never alter.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return SubmitReviewResult{}, err
	}
	data := replayArchiveDoc{Records: []json.RawMessage{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return SubmitReviewResult{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	// Index the stored records by block identity with their decoded
	// content; the embedded version stays raw until the matching
	// conclusion's report has to be proved.
	stored := make([]queryRecord, len(data.Records))
	for i, rawRec := range data.Records {
		var qr queryRecord
		if err := json.Unmarshal(rawRec, &qr); err != nil {
			return SubmitReviewResult{}, fmt.Errorf("archive is corrupted: record %d: %w", i, err)
		}
		stored[i] = qr
	}
	rec, _, ok := findHistoryConclusion(stored, sub.key())
	if !ok {
		return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s",
			ErrUnknownConclusion, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind)
	}
	// A matching conclusion pins its report: prove the declaration the
	// conclusion was produced under before the submission can be accepted,
	// retried or rejected on any later rule. A wholly absent version key is
	// the one legacy shape and means builtin; a written null, an empty
	// object, a partial or wrong-typed declaration, an out-of-range number,
	// an unknown or repeated field — a "builtin" id included — fails the
	// whole submission here, before submission-id reuse and version
	// handling, so neither an identical retry nor any other submission can
	// mask existing damage. Nothing is borrowed from the enabled or a
	// same-id registered version and nothing is re-detected.
	if _, verr := archivedReportVersion(rec.Version); verr != nil {
		return SubmitReviewResult{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, verr)
	}

	// Submission IDs are unique archive-wide. An ID reuse with identical
	// content is an idempotent retry of the original revision; it must
	// succeed (and append nothing) even when the object has since moved on.
	// The target's declaration has already been proved, so retrying a
	// submission stored against a since-decayed report fails above as
	// corruption rather than quietly returning the old revision.
	for i := range data.Reviews {
		obj := &data.Reviews[i]
		for _, rev := range obj.Revisions {
			if rev.SubmissionID != sub.SubmissionID {
				continue
			}
			existing := ReviewSubmission{
				ChainID:         obj.ChainID,
				BlockHash:       obj.BlockHash,
				TxHash:          obj.TxHash,
				Kind:            obj.Kind,
				SubmissionID:    rev.SubmissionID,
				Operator:        rev.Operator,
				Reason:          rev.Reason,
				Status:          rev.Status,
				ExpectedVersion: rev.ExpectedVersion,
			}
			if !sub.contentEqual(existing) {
				return SubmitReviewResult{}, fmt.Errorf("%w: %s", ErrSubmissionConflict, sub.SubmissionID)
			}
			return SubmitReviewResult{
				Created:   false,
				ChainID:   obj.ChainID,
				BlockHash: obj.BlockHash,
				TxHash:    obj.TxHash,
				Kind:      obj.Kind,
				Status:    currentReviewStatus(*obj),
				Version:   len(obj.Revisions),
				Revision:  rev,
			}, nil
		}
	}

	idx := -1
	for i := range data.Reviews {
		if data.Reviews[i].key() == sub.key() {
			idx = i
			break
		}
	}
	if idx >= 0 && data.Reviews[idx].Revisions == nil {
		data.Reviews[idx].Revisions = []ReviewRevision{}
	}
	currentVersion := 0
	if idx >= 0 {
		currentVersion = len(data.Reviews[idx].Revisions)
	}
	if sub.ExpectedVersion != currentVersion {
		return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s is at version %d, submission expected %d",
			ErrReviewConflict, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind, currentVersion, sub.ExpectedVersion)
	}
	rev := sub.revision(currentVersion + 1)
	if idx < 0 {
		data.Reviews = append(data.Reviews, ReviewObject{
			ChainID:   sub.ChainID,
			BlockHash: sub.BlockHash,
			TxHash:    sub.TxHash,
			Kind:      sub.Kind,
			Revisions: []ReviewRevision{rev},
		})
	} else {
		data.Reviews[idx].Revisions = append(data.Reviews[idx].Revisions, rev)
	}
	if err := writeArchiveAtomic(dir, data); err != nil {
		return SubmitReviewResult{}, err
	}
	return SubmitReviewResult{
		Created:   true,
		ChainID:   sub.ChainID,
		BlockHash: sub.BlockHash,
		TxHash:    sub.TxHash,
		Kind:      sub.Kind,
		Status:    sub.Status,
		Version:   currentVersion + 1,
		Revision:  rev,
	}, nil
}

// ReviewOriginal pairs the archived conclusion with the detection version
// (full parameters) that produced it.
type ReviewOriginal struct {
	BlockNumber int64         `json:"blockNumber"`
	Finding     ReportFinding `json:"finding"`
	Version     RuleVersion   `json:"version"`
}

// ReviewHistory is the full revision view of one conclusion object.
type ReviewHistory struct {
	ChainID   string           `json:"chainId"`
	BlockHash string           `json:"blockHash"`
	TxHash    string           `json:"txHash"`
	Kind      string           `json:"kind"`
	Status    string           `json:"status"`
	Version   int              `json:"version"`
	Original  *ReviewOriginal  `json:"original"`
	Revisions []ReviewRevision `json:"revisions"`
}

// currentReviewStatus returns the latest revision's status. A trailing
// "unreviewed" revision means an earlier judgment was withdrawn.
func currentReviewStatus(obj ReviewObject) string {
	if len(obj.Revisions) == 0 {
		return ReviewStatusUnreviewed
	}
	return obj.Revisions[len(obj.Revisions)-1].Status
}

// historyArchiveDoc mirrors the archive file the way a review-history
// query reads it: the target record's embedded version declaration is kept
// as its raw stored document — the same shape a report query, a comparison
// and a review-range evaluation keep it in — while reviews are fully
// decoded. A wrong-typed field in the target's declaration can then be
// re-validated from its raw bytes instead of decoding into silently zeroed
// parameters, and a written null cannot be mistaken for an absent legacy
// key. Damage confined to a registered version or another record the query
// never opens is not part of this document's judgment.
type historyArchiveDoc struct {
	Records []queryRecord  `json:"records"`
	Reviews []ReviewObject `json:"reviews"`
}

// ReviewHistoryQuery returns the current status and version of one
// conclusion object plus every revision in ascending version order. Each
// revision keeps its full submission content, and the response carries the
// original archived conclusion, the detection version parameters and the
// raw swap evidence. An identity without review data reports status
// unreviewed, version 0 and an empty list; when no archived conclusion
// matches the identity, original is null.
//
// When an archived conclusion matches, its report's saved version
// declaration is re-validated from its raw bytes with the exact integrity
// proof a report query enforces before the history is returned: a non-empty
// version identifier, both the sandwich and displacement rules each with a
// boolean enabled and an integer severity 1-5, and a displacement
// multiplier 2-100. A missing or null field or rule object, a wrong type,
// an out-of-range number, an unknown field or rule, or a field declared
// twice in one object (an exact repeat, an escaped spelling or a
// case-only spelling naming the same field, even with identical values)
// makes the saved declaration corrupt; an explicit enabled:false is a
// legal off state but the disabled rule still has to carry complete,
// in-range parameters. Only an old-format record with no "version" key at
// all keeps the built-in interpretation: a written null, an empty object
// or a partial declaration is corruption, and an id of "builtin" is
// validated like every other id rather than bypassing the check.
//
// On corruption the whole query fails with ErrCorruptVersion naming the
// target chain and block, the readable saved version id and the offending
// rule or field — no history JSON and no partial original are returned.
// The legal declaration is used exactly as saved, with parameters never
// zero-filled, completed from the currently enabled or a same-id
// registered version, or re-detected, and its id need not still be
// registered. Damage confined to other records or to the registered
// versions section never blocks the target's history. The query is
// read-only: success or failure rewrites nothing.
func ReviewHistoryQuery(dir, chainID, blockHash, txHash, kind string) (ReviewHistory, error) {
	if strings.TrimSpace(chainID) == "" || strings.TrimSpace(blockHash) == "" ||
		strings.TrimSpace(txHash) == "" {
		return ReviewHistory{}, errors.New("chainId, blockHash and txHash must be non-empty strings")
	}
	if kind != SuppressSandwich && kind != SuppressDisplacement {
		return ReviewHistory{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
	}
	out := ReviewHistory{
		ChainID:   chainID,
		BlockHash: blockHash,
		TxHash:    txHash,
		Kind:      kind,
		Status:    ReviewStatusUnreviewed,
		Version:   0,
		Original:  nil,
		Revisions: []ReviewRevision{},
	}
	key := conclusionKey{chainID, blockHash, txHash, kind}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return out, nil
		}
		return ReviewHistory{}, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return ReviewHistory{}, err
	}
	defer lock.Close()

	// Decode with the target record's embedded version declaration kept as
	// its raw stored document, the same shape a report query uses, so its
	// declaration is re-validated from those bytes rather than decoded into
	// silently zeroed parameters or explained as the built-in rules from a
	// written null.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return ReviewHistory{}, err
	}
	var doc historyArchiveDoc
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &doc); err != nil {
			return ReviewHistory{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	if rec, f, ok := findHistoryConclusion(doc.Records, key); ok {
		// Prove the saved declaration before the original conclusion and its
		// detection parameters are returned. A wholly absent version key is
		// the only legacy shape and means builtin; every declaration that was
		// actually written must stand on its own, and a corrupt one fails the
		// whole query rather than presenting a zero-filled or built-in
		// explanation. A legal declaration is used exactly as saved: nothing is
		// borrowed from the enabled or a registered version, the saved id need
		// not still be registered, and the conclusion is never re-detected.
		version, verr := archivedReportVersion(rec.Version)
		if verr != nil {
			return ReviewHistory{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, verr)
		}
		out.Original = &ReviewOriginal{
			BlockNumber: rec.BlockNumber,
			Finding:     f,
			Version:     version,
		}
	}
	for i := range doc.Reviews {
		obj := doc.Reviews[i]
		if obj.key() != key {
			continue
		}
		out.Version = len(obj.Revisions)
		out.Status = currentReviewStatus(obj)
		out.Revisions = append([]ReviewRevision(nil), obj.Revisions...)
		break
	}
	if out.Revisions == nil {
		out.Revisions = []ReviewRevision{}
	}
	return out, nil
}

// findHistoryConclusion locates the record and the finding for an identity
// among records whose embedded version declaration is still raw.
func findHistoryConclusion(records []queryRecord, key conclusionKey) (*queryRecord, ReportFinding, bool) {
	for i := range records {
		rec := &records[i]
		if rec.ChainID != key.chainID || rec.BlockHash != key.blockHash {
			continue
		}
		for _, f := range rec.Findings {
			if f.TxHash == key.txHash && f.Kind == key.kind {
				return rec, f, true
			}
		}
	}
	return nil, ReportFinding{}, false
}

// ReviewConclusion pairs a conclusion with the rule version whose
// parameters produced it. The finding itself carries the raw swap evidence.
type ReviewConclusion struct {
	Finding ReportFinding `json:"finding"`
	Version RuleVersion   `json:"version"`
}

// ReviewDetail is one evaluated conclusion with its bucket, the revision
// that decided it (null when there is no valid review), the original and
// candidate conclusions (either side may be null), their rule parameters
// and their swap evidence.
type ReviewDetail struct {
	ChainID         string            `json:"chainId"`
	BlockHash       string            `json:"blockHash"`
	BlockNumber     int64             `json:"blockNumber"`
	TxHash          string            `json:"txHash"`
	Kind            string            `json:"kind"`
	Bucket          string            `json:"bucket"`
	AppliedRevision *ReviewRevision   `json:"appliedRevision"`
	Original        *ReviewConclusion `json:"original"`
	Candidate       *ReviewConclusion `json:"candidate"`
}

// ReviewEvaluation is the false-positive analysis over one inclusive height
// range, judged consistently against one archive snapshot and its latest
// review state.
type ReviewEvaluation struct {
	ChainID     string         `json:"chainId"`
	StartHeight uint64         `json:"startHeight"`
	EndHeight   uint64         `json:"endHeight"`
	Version     RuleVersion    `json:"version"`
	Retained    int            `json:"retained"`
	Missed      int            `json:"missed"`
	StillHit    int            `json:"stillHit"`
	Eliminated  int            `json:"eliminated"`
	Pending     int            `json:"pending"`
	Details     []ReviewDetail `json:"details"`
}

// sortReviewDetails orders by height, block hash, tx hash and kind.
func sortReviewDetails(details []ReviewDetail) {
	sort.Slice(details, func(i, j int) bool {
		a, b := details[i], details[j]
		if a.BlockNumber != b.BlockNumber {
			return a.BlockNumber < b.BlockNumber
		}
		if a.BlockHash != b.BlockHash {
			return a.BlockHash < b.BlockHash
		}
		if a.TxHash != b.TxHash {
			return a.TxHash < b.TxHash
		}
		return a.Kind < b.Kind
	})
}

// evaluateRecord mirrors one archived record the way a review-range
// evaluation reads it: every business field is decoded normally, but the
// embedded rule-version declaration is kept as its raw stored document —
// the same shape a report query and alert generation keep it in. The
// decoded struct cannot tell a missing field, an explicit null or a
// wrong-typed value from a real one, so decoding the version into the
// struct would evaluate a decayed report under silently zeroed parameters
// (enabled false, severity 0, a zero displacement multiplier) or explain a
// null declaration as the built-in rules. A wholly absent "version" key is
// the only legacy shape; anything actually saved is kept byte for byte and
// re-validated before the report's conclusions are judged.
type evaluateRecord struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	Swaps       []Swap          `json:"swaps"`
	Findings    []ReportFinding `json:"findings"`
	Version     json.RawMessage `json:"version"`
}

// rawVersionArchiveDoc mirrors the archive file the way a review-range
// evaluation reads it: records keep their embedded version declarations as
// raw stored documents, reviews are fully decoded, and each registered
// version is kept as its raw stored document. A corrupt version entry — a
// wrong-typed field, say — then cannot break the read or masquerade as
// whole-archive corruption; it is judged on its own by intactVersion, so a
// corrupt sibling never contaminates an intact candidate or the built-in
// version, and a corrupt report declaration is that report's corruption,
// judged on its own below.
type rawVersionArchiveDoc struct {
	Records  []evaluateRecord  `json:"records"`
	Versions []json.RawMessage `json:"versions"`
	Reviews  []ReviewObject    `json:"reviews"`
}

// EvaluateReviews re-judges every archived block on chainID in the inclusive
// range [startHeight, endHeight] under the given registered rule version and
// compares the candidate conclusions against archived originals, using only
// archived evidence and the latest review state. Only original conclusions
// marked real or false positive feed the four counts: real risks split into
// retained (same tx and same kind still hits; severity changes do not
// matter) and missed; false positives split into still hit and eliminated.
// A candidate hit on the same tx and kind without a valid (non-withdrawn)
// review counts as pending, as does the new kind when the candidate changes
// a tx's conclusion type; withdrawn objects behave as unreviewed. The call
// is read-only: reports, the enabled version, reviews and alert records are
// never modified. An empty range yields zero counts and an empty list. The
// named candidate's stored document must still satisfy the registration
// rules in full — both rules declared with non-null, well-typed, in-range
// parameters, including a rule explicitly disabled (enabled:false) — or the
// whole evaluation fails with ErrCorruptVersion before any judgment, even
// when the range contains no blocks; the corrupt content is never replaced
// by defaults, the currently enabled version or the built-in rules. A
// corrupt version the call does not name never blocks an intact candidate.
//
// Every archived report in the range must likewise still carry an intact
// version declaration — the same proof a report query demands, re-validated
// from the raw stored document with the parser registrations pass. A
// missing or null field or rule object, a wrong type, an out-of-range
// number, an unknown field or rule, or a field declared twice in one object
// makes the whole evaluation fail with ErrCorruptVersion naming the chain,
// the block, the readable saved version id and the offending rule or field
// — even when that report has no swaps, no conclusions or no valid review,
// and no partial statistics or details are produced. Only an old-format
// record with no "version" key at all keeps the built-in interpretation; an
// explicit null, an empty object or a partial declaration is corruption,
// and an id of "builtin" is validated like any other. A legal declaration
// is used exactly as saved: parameters are never completed from the enabled
// or a registered version, and the id need not still be registered. A
// report outside the chain or range whose declaration alone is damaged
// never blocks the evaluation. A failed evaluation changes nothing.
func EvaluateReviews(dir, chainID string, startHeight, endHeight uint64, versionID string) (ReviewEvaluation, error) {
	if strings.TrimSpace(chainID) == "" {
		return ReviewEvaluation{}, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(versionID) == "" {
		return ReviewEvaluation{}, errors.New("version id must not be empty")
	}
	if startHeight > endHeight {
		return ReviewEvaluation{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	result := ReviewEvaluation{
		ChainID:     chainID,
		StartHeight: startHeight,
		EndHeight:   endHeight,
		Details:     []ReviewDetail{},
	}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			// An absent archive has only the built-in version registered, so
			// any other id is an unknown version even though the range would
			// match no blocks.
			if versionID != BuiltinVersionID {
				return ReviewEvaluation{}, fmt.Errorf("%w: %s", ErrUnknownVersion, versionID)
			}
			result.Version = BuiltinVersion()
			return result, nil
		}
		return ReviewEvaluation{}, serr
	}
	// One shared lock for the whole evaluation: the archive snapshot and the
	// latest review state stay consistent across every block.
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	defer lock.Close()

	// Decode with each record's embedded version declaration and each
	// registered version kept as its raw stored document, so a wrong-typed
	// field in one declaration is that report's or that version's
	// corruption, not whole-archive corruption: the candidate's document is
	// re-validated from its bytes the same way a single-block comparison
	// proves its version intact, and every in-range report's declaration is
	// re-validated from its bytes exactly the way a report query proves it,
	// rather than decoded into silently zeroed parameters or a
	// null-explained built-in report.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	var doc rawVersionArchiveDoc
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &doc); err != nil {
			return ReviewEvaluation{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	// The requested version must be intact in the archive: re-validate its
	// stored document before judging anything, so a corrupt version fails
	// the same way even when the range matches no blocks, has no swaps or
	// carries no valid manual review.
	candidate, err := intactVersion(doc.Versions, versionID)
	if err != nil {
		return ReviewEvaluation{}, err
	}
	result.Version = candidate

	reviews := make(map[conclusionKey]*ReviewObject, len(doc.Reviews))
	for i := range doc.Reviews {
		reviews[doc.Reviews[i].key()] = &doc.Reviews[i]
	}

	details := []ReviewDetail{}
	for _, rec := range doc.Records {
		if rec.ChainID != chainID {
			continue
		}
		height := uint64(rec.BlockNumber)
		if height < startHeight || height > endHeight {
			continue
		}
		// Prove the saved declaration before any of the report's conclusions
		// is judged — and even when none would be. A wholly absent version
		// key is the only legacy shape and means builtin; every declaration
		// that was actually written must stand on its own, and a corrupt one
		// fails the whole evaluation before any statistic or detail is
		// produced. Reports on other chains or outside the range are never
		// opened.
		originalVersion, err := archivedReportVersion(rec.Version)
		if err != nil {
			return ReviewEvaluation{}, corruptReportError(chainID, rec.BlockHash, rec.Version, err)
		}
		candidateFindings := DetectBlockWithRules(rec.Swaps, candidate.Rules)
		candByKey := make(map[conclusionKey]ReportFinding, len(candidateFindings))
		candByTx := make(map[string]ReportFinding, len(candidateFindings))
		for _, cf := range candidateFindings {
			candByKey[conclusionKey{rec.ChainID, rec.BlockHash, cf.TxHash, cf.Kind}] = cf
			candByTx[cf.TxHash] = cf
		}

		// Original conclusions: only reviewed (real/false-positive) ones
		// enter the four counts; same-kind candidate hits without a valid
		// review are pending; originals that simply vanished without review
		// are not counted anywhere.
		for _, of := range rec.Findings {
			key := conclusionKey{rec.ChainID, rec.BlockHash, of.TxHash, of.Kind}
			obj := reviews[key]
			original := &ReviewConclusion{Finding: of, Version: originalVersion}
			if obj == nil || currentReviewStatus(*obj) == ReviewStatusUnreviewed {
				if cf, ok := candByKey[key]; ok {
					details = append(details, ReviewDetail{
						ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
						TxHash: of.TxHash, Kind: of.Kind, Bucket: BucketPending,
						Original: original, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
					})
				}
				continue
			}
			rev := obj.Revisions[len(obj.Revisions)-1]
			detail := ReviewDetail{
				ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
				TxHash: of.TxHash, Kind: of.Kind, AppliedRevision: &rev, Original: original,
			}
			cf, hit := candByKey[key]
			if hit {
				detail.Candidate = &ReviewConclusion{Finding: cf, Version: candidate}
			}
			switch rev.Status {
			case ReviewStatusReal:
				if hit {
					detail.Bucket = BucketRetained
				} else {
					detail.Bucket = BucketMissed
				}
			case ReviewStatusFalsePositive:
				if hit {
					detail.Bucket = BucketStillHit
				} else {
					detail.Bucket = BucketEliminated
				}
			}
			details = append(details, detail)
		}

		// Candidate conclusions whose (tx, kind) matches no original: when
		// the same tx carried a different original kind this is the "new
		// type" side of a type change; either way it is unreviewed and
		// pending.
		for _, cf := range candidateFindings {
			if _, sameKind := findOriginalFinding(rec, cf.TxHash, cf.Kind); sameKind {
				continue
			}
			details = append(details, ReviewDetail{
				ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
				TxHash: cf.TxHash, Kind: cf.Kind, Bucket: BucketPending,
				Original: nil, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
			})
		}
	}

	for _, d := range details {
		switch d.Bucket {
		case BucketRetained:
			result.Retained++
		case BucketMissed:
			result.Missed++
		case BucketStillHit:
			result.StillHit++
		case BucketEliminated:
			result.Eliminated++
		case BucketPending:
			result.Pending++
		}
	}
	sortReviewDetails(details)
	result.Details = details
	return result, nil
}

func findOriginalFinding(rec evaluateRecord, txHash, kind string) (ReportFinding, bool) {
	for _, f := range rec.Findings {
		if f.TxHash == txHash && f.Kind == kind {
			return f, true
		}
	}
	return ReportFinding{}, false
}

package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
	"syscall"
)

// Offline alerting turns conclusions already stored in an archive into
// alert processing records. It never re-runs detection: a record always
// reflects the finding, the rule version and the parameters that were in
// force when the block was archived.

// Alert statuses. A finding above the generation threshold becomes an
// "alert"; a finding that matches one or more registered suppression
// conditions at its block height becomes "suppressed" instead.
const (
	AlertStatusAlert      = "alert"
	AlertStatusSuppressed = "suppressed"
)

// Suppression condition kinds.
const (
	SuppressSandwich     = "sandwich"
	SuppressDisplacement = "displacement"
)

// ErrUnknownKind reports a conclusion/condition kind that is neither
// sandwich nor displacement.
var ErrUnknownKind = errors.New("unknown kind")

// ErrSuppressionConflict reports re-registering an existing suppression ID
// with different content.
var ErrSuppressionConflict = errors.New("suppression already registered with different content")

// ErrUnknownSuppression reports revoking a condition ID that is not
// registered in the archive (including the empty archive).
var ErrUnknownSuppression = errors.New("unknown suppression condition")

// SuppressionHit records one suppression condition that matched an event.
type SuppressionHit struct {
	ID     string `json:"id"`
	Reason string `json:"reason"`
}

// ProcessingRecord is one fully resolved alerting outcome. Its identity is
// (chain, block hash, victim tx hash, conclusion kind, channel): once a
// record exists for that identity, no later import, wider or overlapping
// height range, rule-version switch or restart can produce it again. The
// record keeps the complete block identity, pool, conclusion, raw swap
// evidence, the detection version and its parameters, the threshold used at
// generation time, and every suppression condition that matched.
type ProcessingRecord struct {
	ChainID      string           `json:"chainId"`
	BlockHash    string           `json:"blockHash"`
	BlockNumber  uint64           `json:"blockNumber"`
	Pool         string           `json:"pool"`
	Channel      string           `json:"channel"`
	Finding      ReportFinding    `json:"finding"`
	Version      RuleVersion      `json:"version"`
	MinSeverity  int              `json:"minSeverity"`
	Status       string           `json:"status"`
	Suppressions []SuppressionHit `json:"suppressions"`
}

func (r ProcessingRecord) identity() alertKey {
	return alertKey{
		chainID:   r.ChainID,
		blockHash: r.BlockHash,
		txHash:    r.Finding.TxHash,
		kind:      r.Finding.Kind,
		channel:   r.Channel,
	}
}

// Suppression is one registered suppression condition. Every field matches
// exactly (the pool is matched against the pool of the victim swap's
// original exchange record), and an event at height h is covered when
// StartHeight <= h <= EndHeight.
//
// Revoked marks a condition whose user has withdrawn it. A revoked
// condition is kept for audit but never matches later processing; the
// field is always serialized (an absent value in an old archive decodes
// to false, i.e. not revoked) and cannot be set through a registration
// document. Revocation applies to findings processed afterwards only —
// event height never decides when it takes effect.
type Suppression struct {
	ID          string `json:"id"`
	ChainID     string `json:"chainId"`
	Pool        string `json:"pool"`
	Kind        string `json:"kind"`
	Channel     string `json:"channel"`
	StartHeight uint64 `json:"startHeight"`
	EndHeight   uint64 `json:"endHeight"`
	Reason      string `json:"reason"`
	Revoked     bool   `json:"revoked"`
}

// covers reports whether the suppression applies to an event on chain at
// height in the given pool/kind/channel. Matching depends only on the
// event's height, never on operation time, import order or the archive's
// highest block.
func (s Suppression) covers(chainID, pool, kind, channel string, height uint64) bool {
	return s.ChainID == chainID && s.Pool == pool && s.Kind == kind && s.Channel == channel &&
		s.StartHeight <= height && height <= s.EndHeight
}

// alertKey is the deduplication identity of a processing record.
type alertKey struct {
	chainID   string
	blockHash string
	txHash    string
	kind      string
	channel   string
}

// suppressionSpec mirrors one suppression registration document. Pointers
// distinguish missing fields from explicit zero values; heights are parsed
// separately as unsigned 64-bit integers.
type suppressionSpec struct {
	ID          *string `json:"id"`
	ChainID     *string `json:"chainId"`
	Pool        *string `json:"pool"`
	Kind        *string `json:"kind"`
	Channel     *string `json:"channel"`
	StartHeight *uint64 `json:"startHeight"`
	EndHeight   *uint64 `json:"endHeight"`
	Reason      *string `json:"reason"`
}

func nonEmpty(field string, v *string) (string, error) {
	if v == nil {
		return "", fmt.Errorf("%s is required (non-empty string)", field)
	}
	if strings.TrimSpace(*v) == "" {
		return "", fmt.Errorf("%s must be a non-empty string", field)
	}
	return *v, nil
}

// suppressionFields lists every field name a registration document may
// declare, in the struct's JSON spelling.
var suppressionFields = []string{"id", "chainId", "pool", "kind", "channel", "startHeight", "endHeight", "reason"}

// suppressionScanPolicy validates the shape of a suppression document with
// the shared scanner. Unlike the version document, a suppression document
// is flat: nested values carry no field table of their own, and only known
// fields take part in duplicate detection (an unknown key is left for the
// typed decoder to reject).
var suppressionScanPolicy = specPolicy{
	topObject:          "suppression spec",
	known:              fieldTable(suppressionFields...),
	rejectExactUnknown: false,
	firstTokenError: func(err error) error {
		return fmt.Errorf("invalid suppression spec: %w", err)
	},
	nonObject: func(json.Token) error {
		return errors.New("invalid suppression spec: expected a single JSON object")
	},
	wrap: func(err error) error {
		return fmt.Errorf("invalid suppression spec: %w", err)
	},
	duplicate: func(_ string, canonical, first, spelling string) error {
		return fmt.Errorf("invalid suppression spec: duplicate field %q (declared as %q and %q)", canonical, first, spelling)
	},
	trailing: suppressionTrailingData,
}

// validateSuppressionDocument checks the raw registration input
// structurally before any field is read: it must hold exactly one complete
// JSON object — leading and trailing whitespace is fine, but empty input,
// arrays, null, scalars and incomplete objects are not, and no byte other
// than whitespace may follow the closing brace (a second object, an extra
// } or ] or any other JSON value is rejected). Inside the object every
// known field may be declared at most once: field names are compared after
// JSON unescaping with the decoder's own field-name folding, and two
// spellings that resolve to the same field — differing only in case, like
// channel and CHANNEL, or in a compatibility character, like U+017F for
// s — count as one duplicate declaration even when both carry the same
// value.
func validateSuppressionDocument(raw []byte) error {
	return scanJSONObject(raw, suppressionScanPolicy)
}

// suppressionTrailingData mirrors decoding one more value after the
// object: the only legal remainder is whitespace, which reports io.EOF;
// a second value or an unmatched bracket yields any other error and is
// trailing data.
func suppressionTrailingData(raw []byte, offset int) error {
	dec := json.NewDecoder(bytes.NewReader(raw[offset:]))
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return errors.New("invalid suppression spec: unexpected trailing data")
	}
	return nil
}

// ParseSuppression validates one registration document. Only sandwich and
// displacement kinds exist, every text field must be non-empty, heights are
// unsigned 64-bit integers and the start height must not exceed the end
// height.
func ParseSuppression(raw []byte) (Suppression, error) {
	if err := validateSuppressionDocument(raw); err != nil {
		return Suppression{}, err
	}
	var spec suppressionSpec
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&spec); err != nil {
		return Suppression{}, fmt.Errorf("invalid suppression spec: %w", err)
	}
	id, err := nonEmpty("id", spec.ID)
	if err != nil {
		return Suppression{}, err
	}
	chainID, err := nonEmpty("chainId", spec.ChainID)
	if err != nil {
		return Suppression{}, err
	}
	pool, err := nonEmpty("pool", spec.Pool)
	if err != nil {
		return Suppression{}, err
	}
	kind, err := nonEmpty("kind", spec.Kind)
	if err != nil {
		return Suppression{}, err
	}
	if kind != SuppressSandwich && kind != SuppressDisplacement {
		return Suppression{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
	}
	channel, err := nonEmpty("channel", spec.Channel)
	if err != nil {
		return Suppression{}, err
	}
	if spec.StartHeight == nil {
		return Suppression{}, errors.New("startHeight is required (unsigned 64-bit integer)")
	}
	if spec.EndHeight == nil {
		return Suppression{}, errors.New("endHeight is required (unsigned 64-bit integer)")
	}
	if *spec.StartHeight > *spec.EndHeight {
		return Suppression{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", *spec.StartHeight, *spec.EndHeight)
	}
	reason, err := nonEmpty("reason", spec.Reason)
	if err != nil {
		return Suppression{}, err
	}
	return Suppression{
		ID:          id,
		ChainID:     chainID,
		Pool:        pool,
		Kind:        kind,
		Channel:     channel,
		StartHeight: *spec.StartHeight,
		EndHeight:   *spec.EndHeight,
		Reason:      reason,
	}, nil
}

// ParseHeight parses a non-negative 64-bit integer height. Signs, fractions,
// blanks and values above 2^64-1 are rejected.
func ParseHeight(text string) (uint64, error) {
	if text == "" {
		return 0, errors.New("height must be a non-empty unsigned 64-bit integer")
	}
	h, err := strconv.ParseUint(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid height %q: %w", text, err)
	}
	return h, nil
}

// ValidateSeverity accepts the integer threshold range 1..5 inclusive; the
// threshold itself counts as a hit.
func ValidateSeverity(severity int) error {
	if severity < 1 || severity > 5 {
		return fmt.Errorf("minSeverity must be between 1 and 5, got %d", severity)
	}
	return nil
}

// suppressionEqual reports whether two conditions carry identical
// registration content. Revoked state is intentionally excluded: retrying
// the same document is idempotent even after the condition was revoked
// (and never re-enables it), while differing content still conflicts.
func suppressionEqual(a, b Suppression) bool {
	return a.ID == b.ID &&
		a.ChainID == b.ChainID &&
		a.Pool == b.Pool &&
		a.Kind == b.Kind &&
		a.Channel == b.Channel &&
		a.StartHeight == b.StartHeight &&
		a.EndHeight == b.EndHeight &&
		a.Reason == b.Reason
}

// matchSuppressions returns every active condition covering the event,
// sorted by ID in lexicographic order so overlapping conditions are
// reported deterministically. Revoked conditions are skipped: they no
// longer apply to conclusions processed after the revocation.
func matchSuppressions(conds []Suppression, chainID, pool, kind, channel string, height uint64) []SuppressionHit {
	hits := []SuppressionHit{}
	for _, s := range conds {
		if s.Revoked {
			continue
		}
		if s.covers(chainID, pool, kind, channel, height) {
			hits = append(hits, SuppressionHit{ID: s.ID, Reason: s.Reason})
		}
	}
	sort.Slice(hits, func(i, j int) bool { return hits[i].ID < hits[j].ID })
	return hits
}

// victimPool returns the pool of the victim swap inside the finding's raw
// evidence. The victim is the swap whose TxHash matches the finding; the
// evidence ordering and count vary by conclusion kind, so the pool is read
// off the original exchange record rather than inferred from position.
func victimPool(f ReportFinding) (string, bool) {
	for _, s := range f.Evidence {
		if s.TxHash == f.TxHash {
			return s.Pool, true
		}
	}
	return "", false
}

// sortRecords orders processing records by height, block hash, tx hash and
// kind ascending. Channel stays out of the ordering key: generation runs for
// one channel, history may span several.
func sortRecords(records []ProcessingRecord) {
	sort.Slice(records, func(i, j int) bool {
		a, b := records[i], records[j]
		if a.BlockNumber != b.BlockNumber {
			return a.BlockNumber < b.BlockNumber
		}
		if a.BlockHash != b.BlockHash {
			return a.BlockHash < b.BlockHash
		}
		if a.Finding.TxHash != b.Finding.TxHash {
			return a.Finding.TxHash < b.Finding.TxHash
		}
		return a.Finding.Kind < b.Finding.Kind
	})
}

// alertRecord mirrors one archived record the way alert generation reads
// and writes it: every business field is decoded normally, but the embedded
// rule-version declaration is kept as its raw stored document — the same
// shape a report query keeps it in. The decoded struct cannot tell a
// missing field, an explicit null or a wrong-typed value from a real one,
// so decoding the version into the struct would process a decayed report
// under silently zeroed parameters (enabled false, severity 0, a zero
// displacement multiplier) or explain a null declaration as the built-in
// rules. A wholly absent "version" key is the only legacy shape; anything
// actually saved is kept byte for byte and re-validated before the report's
// conclusions are processed, and written back unchanged.
type alertRecord struct {
	ChainID     string          `json:"chainId"`
	BlockHash   string          `json:"blockHash"`
	BlockNumber int64           `json:"blockNumber"`
	Swaps       []Swap          `json:"swaps"`
	Findings    []ReportFinding `json:"findings"`
	Version     json.RawMessage `json:"version,omitempty"`
}

// alertArchiveDoc mirrors the archive file the way alert generation reads
// and writes it: records keep their embedded version declarations as raw
// stored documents, and registered versions are kept raw too — generation
// never consults the registry, so a corrupt registered version is that
// version's damage, not whole-archive corruption, and is written back byte
// for byte. Suppressions, processing records and reviews are decoded fully.
type alertArchiveDoc struct {
	Records        []alertRecord      `json:"records"`
	Versions       []json.RawMessage  `json:"versions,omitempty"`
	EnabledVersion string             `json:"enabledVersion,omitempty"`
	Suppressions   []Suppression      `json:"suppressions,omitempty"`
	AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
	Reviews        []ReviewObject     `json:"reviews,omitempty"`
}

// GenerateAlerts turns archived conclusions in the inclusive range
// [startHeight, endHeight] on chainID for channel into new processing
// records. Detection is not re-run: the archived finding, evidence and rule
// version are reused. A finding at least minSeverity is processed; findings
// below the threshold leave no record, so lowering the threshold later can
// still produce them. Every already-processed identity is skipped, which
// makes repeated imports, repeated generation, wider or overlapping ranges,
// version switches and restarts idempotent. Channels are independent, and
// blocks at the same height with different hashes are handled separately.
//
// All new records of one call are committed together or not at all. The
// returned slice contains only records created by this call (alerts and
// suppressions distinguished), sorted by height, block hash, tx hash and
// kind; an empty result serializes as [].
//
// Every archived report in the range must still carry an intact version
// declaration — the same proof a report query demands, re-validated from
// the raw stored document with the parser registrations pass. A missing or
// null field or rule object, a wrong type, an out-of-range number, an
// unknown field or rule, or a field declared twice in one object makes the
// whole generation fail with ErrCorruptVersion naming the chain, the block,
// the readable saved version id and the offending rule or field — even when
// that report has no conclusions, every conclusion is below the threshold,
// or every conclusion was already processed. Only an old-format record with
// no "version" key at all keeps the built-in interpretation; an explicit
// null, an empty object or a partial declaration is corruption, and an id
// of "builtin" is validated like any other. A legal declaration is used
// exactly as saved: parameters are never completed from the enabled or a
// registered version, and the id need not still be registered. A failed
// generation changes nothing: reports, existing processing records and
// suppressions are all left untouched.
func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
	if strings.TrimSpace(chainID) == "" {
		return nil, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(channel) == "" {
		return nil, errors.New("channel must be a non-empty name")
	}
	if err := ValidateSeverity(minSeverity); err != nil {
		return nil, err
	}
	if startHeight > endHeight {
		return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	// Decode with each record's embedded version declaration kept as its
	// raw stored document, the same shape a report query uses: a decayed
	// declaration is that report's corruption, judged on its own below,
	// rather than whole-archive corruption or silently zeroed parameters.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return nil, err
	}
	data := alertArchiveDoc{Records: []alertRecord{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return nil, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	processed := make(map[alertKey]struct{}, len(data.AlertRecords))
	for _, r := range data.AlertRecords {
		processed[r.identity()] = struct{}{}
	}

	created := []ProcessingRecord{}
	for _, rec := range data.Records {
		if rec.ChainID != chainID {
			continue
		}
		height := uint64(rec.BlockNumber)
		if height < startHeight || height > endHeight {
			continue
		}
		// Prove the saved declaration before any of the report's
		// conclusions is processed — and even when none would be. A wholly
		// absent version key is the only legacy shape and means builtin;
		// every declaration that was actually written must stand on its
		// own, and a corrupt one fails the whole generation before
		// anything is written.
		version, err := archivedReportVersion(rec.Version)
		if err != nil {
			return nil, corruptReportError(chainID, rec.BlockHash, rec.Version, err)
		}
		for _, f := range rec.Findings {
			if f.Severity < minSeverity {
				// Below the threshold: no record is written, so the event
				// stays eligible after a later threshold reduction.
				continue
			}
			key := alertKey{
				chainID:   rec.ChainID,
				blockHash: rec.BlockHash,
				txHash:    f.TxHash,
				kind:      f.Kind,
				channel:   channel,
			}
			if _, ok := processed[key]; ok {
				continue
			}
			pool, ok := victimPool(f)
			if !ok {
				return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
					rec.ChainID, rec.BlockHash, f.TxHash)
			}
			hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
			status := AlertStatusAlert
			if len(hits) > 0 {
				status = AlertStatusSuppressed
			}
			record := ProcessingRecord{
				ChainID:      rec.ChainID,
				BlockHash:    rec.BlockHash,
				BlockNumber:  height,
				Pool:         pool,
				Channel:      channel,
				Finding:      f,
				Version:      version,
				MinSeverity:  minSeverity,
				Status:       status,
				Suppressions: hits,
			}
			created = append(created, record)
			processed[key] = struct{}{}
		}
	}
	sortRecords(created)
	if len(created) > 0 {
		data.AlertRecords = append(data.AlertRecords, created...)
		if err := writeArchiveAtomic(dir, data); err != nil {
			return nil, err
		}
	}
	return created, nil
}

// AlertHistory returns stored processing records on chainID for channel in
// the inclusive range [startHeight, endHeight]. It only reads the archive;
// suppressions registered afterwards cannot alter the stored content.
func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
	if strings.TrimSpace(chainID) == "" {
		return nil, errors.New("chainId must be a non-empty string")
	}
	if strings.TrimSpace(channel) == "" {
		return nil, errors.New("channel must be a non-empty name")
	}
	if startHeight > endHeight {
		return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
	}
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return []ProcessingRecord{}, nil
		}
		return nil, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return nil, err
	}
	out := []ProcessingRecord{}
	for _, r := range data.AlertRecords {
		if r.ChainID != chainID || r.Channel != channel {
			continue
		}
		if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
			continue
		}
		out = append(out, r)
	}
	sortRecords(out)
	return out, nil
}

// RegisterSuppression validates raw and stores one suppression condition in
// the archive. Re-registering the same ID with identical content succeeds
// without adding anything (created is false) — this stays true after the
// condition was revoked and never re-enables it; the same ID with different
// content is rejected. New conditions only affect conclusions that have not
// been processed yet: historical alerts are never rewritten as suppressed,
// and suppressed records are not re-alerted when a condition's range ends.
// The registration document cannot set revoked state.
func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
	s, err = ParseSuppression(raw)
	if err != nil {
		return Suppression{}, false, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return Suppression{}, false, err
	}
	lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if lerr != nil {
		return Suppression{}, false, lerr
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return Suppression{}, false, err
	}
	for _, existing := range data.Suppressions {
		if existing.ID == s.ID {
			if suppressionEqual(existing, s) {
				return existing, false, nil
			}
			return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
		}
	}
	data.Suppressions = append(data.Suppressions, s)
	if err := writeArchiveAtomic(dir, data); err != nil {
		return Suppression{}, false, err
	}
	return s, true, nil
}

// RevokeSuppression withdraws the condition with the given exact ID. The
// first successful revocation returns changed=true and the full condition
// with Revoked set; revoking the same ID again succeeds with changed=false.
// A blank ID is rejected, and an ID that was never registered — including
// any ID in an empty archive — returns ErrUnknownSuppression. The revoked
// condition is retained (still listed) but stops matching conclusions
// processed from now on; it cannot be revived, a fresh ID is required to
// suppress again.
//
// The revocation is committed atomically under the archive lock: a busy
// archive, a corrupted one or a failed save leaves every condition, report
// and processing record untouched. One generation run always sees either
// the pre- or the post-revocation condition set in full.
func RevokeSuppression(dir, id string) (s Suppression, changed bool, err error) {
	if strings.TrimSpace(id) == "" {
		return Suppression{}, false, errors.New("suppression id must be a non-empty string")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return Suppression{}, false, err
	}
	lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if lerr != nil {
		return Suppression{}, false, lerr
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return Suppression{}, false, err
	}
	for i := range data.Suppressions {
		if data.Suppressions[i].ID != id {
			continue
		}
		if data.Suppressions[i].Revoked {
			return data.Suppressions[i], false, nil
		}
		data.Suppressions[i].Revoked = true
		if err := writeArchiveAtomic(dir, data); err != nil {
			return Suppression{}, false, err
		}
		return data.Suppressions[i], true, nil
	}
	return Suppression{}, false, fmt.Errorf("%w: %s", ErrUnknownSuppression, id)
}

// ListSuppressions returns every suppression condition stored in the
// archive, ordered by ID. A read on an absent archive returns an empty list.
func ListSuppressions(dir string) ([]Suppression, error) {
	if _, serr := os.Stat(dir); serr != nil {
		if errors.Is(serr, os.ErrNotExist) {
			return []Suppression{}, nil
		}
		return nil, serr
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return nil, err
	}
	defer lock.Close()

	data, err := readArchive(dir)
	if err != nil {
		return nil, err
	}
	out := append([]Suppression(nil), data.Suppressions...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	if out == nil {
		out = []Suppression{}
	}
	return out, nil
}

