311				path := filepath.Join(dir, archiveFileName)
312				text := string(readArchiveFile(t, dir))
313				// The first candC declaration in the file is the one embedded
314				// in the record (records precede the versions registry).
315				versionsAt := strings.Index(text, `"versions":`)
316				if versionsAt < 0 {
317					t.Fatal("versions section not found")
318				}
319				at := strings.Index(text[:versionsAt], `"id": "candC"`)
320				if at < 0 {
321					t.Fatal("record's embedded candC declaration not found")
322				}
323				anchor := `"severity": 4,`
324				field := strings.Index(text[at:versionsAt], anchor)
325				if field < 0 {
326					t.Fatal("severity field not found in embedded declaration")
327				}
328				pos := at + field
329				patched := text[:pos] + dup.field + text[pos:]
330				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
331					t.Fatal(err)
332				}
