336				}
337				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
338					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
339				}
340				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
341					t.Fatalf("error must name candC and severity, got %v", err)
342				}
343				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
344					t.Fatal("failed generation repaired the duplicate field")
345				}
346			})
347		}
348	}
349	
350	// TestGenerateDisabledAndUnregisteredDeclarationsAccepted proves a legal
351	// declaration is used exactly as saved: an explicit enabled:false is a
352	// legal off state, and the saved id need not still be registered — the
353	// record carries the declaration's own complete parameters, never values
354	// pulled from the enabled or a same-id registered version.
355	func TestGenerateDisabledAndUnregisteredDeclarationsAccepted(t *testing.T) {
356		dir := setupCorruptCompareArchive(t)
357		ghost := map[string]any{
358			"id": "ghost",
359			"rules": map[string]any{
360				"sandwich":     map[string]any{"enabled": false, "severity": 1},
361				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 100},
362			},
363		}
364		replaceStoredReportVersion(t, dir, "1", "0xblk", ghost)
365		got, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
366		if err != nil {
367			t.Fatalf("unregistered but complete declaration must generate: %v", err)
368		}
369		if len(got) != 1 {
370			t.Fatalf("got %d records, want 1: %+v", len(got), got)
371		}
372		v := got[0].Version
373		if v.ID != "ghost" || v.Rules.Sandwich.Enabled ||
374			!v.Rules.Displacement.Enabled || v.Rules.Displacement.Severity != 5 ||
375			v.Rules.Displacement.Multiplier != 100 {
376			t.Fatalf("record must carry the saved declaration's own parameters: %+v", v)
377		}
378	
379		// The same-id registered version's parameters are never substituted
380		// for the saved ones: rewrite the embedded declaration's displacement
381		// severity and confirm the record keeps the saved value.
382		dir = setupCorruptCompareArchive(t)
383		rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
384			storedRule(t, ver, "displacement")["severity"] = 2
385		})
386		got, err = GenerateAlerts(dir, "1", "ops", 0, 100, 1)
387		if err != nil {
388			t.Fatalf("saved declaration must generate: %v", err)
389		}
390		if len(got) != 1 || got[0].Version.Rules.Displacement.Severity != 2 {
391			t.Fatalf("record must use the saved parameters, not the registry's: %+v", got)
392		}
393	}
394	
395	// TestGenerateCorruptVersionOutsideRangeIgnored proves the integrity check
396	// covers exactly the reports the generation draws on: a decayed
397	// declaration outside the height range or on another chain does not block
398	// the run, and the corrupt document is written back byte for byte.
399	func TestGenerateCorruptVersionOutsideRangeIgnored(t *testing.T) {
400		dir := setupCorruptCompareArchive(t) // 0xblk at height 7
401		replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
402	
403		// A range below the corrupt report sees an empty result, not a failure.
404		got, err := GenerateAlerts(dir, "1", "ops", 8, 100, 1)
405		if err != nil {
406			t.Fatalf("out-of-range corrupt report must not block generation: %v", err)
407		}
408		if len(got) != 0 {
409			t.Fatalf("got %+v, want no records", got)
410		}
411		// Another chain's range is equally unaffected.
412		if _, err := GenerateAlerts(dir, "2", "ops", 0, 100, 1); err != nil {
413			t.Fatalf("other chain must not see the corrupt report: %v", err)
414		}
415		// The corrupt declaration survived the successful runs untouched.
416		text := string(readArchiveFile(t, dir))
417		if !strings.Contains(text, `"version": null`) {
418			t.Fatal("successful generation rewrote the corrupt declaration")
419		}
420	}
